    httpStatus: payload.httpStatus === 200 ? 200 : 202,
    category: typeof payload.category === 'string' ? payload.category : null,
    statusUrl,
    generatedAt: typeof payload.generatedAt === 'string' ? payload.generatedAt : new Date().toISOString(),
  };
